#include "genesis/perception/pipeline.hpp"
#include "genesis/runtime/runtime.hpp"
#include <chrono>
#include <iostream>
#include <string>
int main(){using namespace genesis;perception::PerceptionPipeline p("benchmark",1,10000,10000);if(!p.declare_route({"text-local","benchmark-provider",runtime::sha256("artifact"),"test-only",runtime::sha256("declaration"),{},{},perception::Modality::text,perception::RouteEvidenceState::declared}))return 1;for(std::size_t i=0;i<3;++i)if(!p.record_probe("text-local",true,runtime::sha256("probe-"+std::to_string(i)),i))return 2;if(!p.qualify_route("text-local",runtime::sha256("qualification"),4))return 3;const auto start=std::chrono::steady_clock::now();for(std::size_t i=0;i<10000;++i){const auto n=std::to_string(i);if(!p.ingest({"observation-"+n,"text-local",runtime::sha256("payload-"+n),runtime::sha256("provenance-"+n),i,i,.9,.1})||!p.derive({"feature-"+n,"observation-"+n,"token",runtime::sha256("value-"+n),runtime::sha256("derivation-"+n),.8,.2}))return 4;}const auto end=std::chrono::steady_clock::now();if(!p.verify()||p.project("observation-9999",4).action_authorized)return 5;std::cout<<"observations="<<p.observations().size()<<" features="<<p.features().size()<<" seconds="<<std::chrono::duration<double>(end-start).count()<<'\n';}
